#!/usr/bin/env bash
# Documentation : extraits et mentions remis à jour après le nettoyage.
# Prérequis : apply-fix-nettoyage.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-nettoyage.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/domaine/les-conventions.mdx" 2>/dev/null | grep -qF "La page d’un évènement : seules les disciplines publiées sont nommées"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "la page le décide elle-même en lisant la base (editorialGate)" "packages/backend/src/modules/pageVisibility/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-nettoyage.sh"; exit 1; }
